package com.turing.app.api.interview.entity;
import com.turing.app.api.application.entity.Application;import com.turing.app.api.user.entity.User;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="interviews") public class Interview{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="application_id")private Application application;@Column(name="starts_at",nullable=false)private Instant startsAt;@Column(name="ends_at",nullable=false)private Instant endsAt;@Enumerated(EnumType.STRING)@Column(nullable=false,length=16)private InterviewStatus status;@Enumerated(EnumType.STRING)@Column(name="location_type",nullable=false,length=16)private InterviewLocationType locationType;@Column(length=300)private String location;@Column(name="meeting_url",length=1000)private String meetingUrl;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="created_by")private User createdBy;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version@Column(nullable=false)private long version;protected Interview(){}public static Interview create(Application app,User actor,Instant starts,Instant ends,InterviewLocationType type,String location,String url,Instant now){Interview v=new Interview();v.id=UUID.randomUUID();v.application=app;v.createdBy=actor;v.status=InterviewStatus.SCHEDULED;v.createdAt=now;v.updateSchedule(starts,ends,type,location,url,now);return v;}public void updateSchedule(Instant starts,Instant ends,InterviewLocationType type,String location,String url,Instant now){startsAt=starts;endsAt=ends;locationType=type;this.location=location;meetingUrl=url;updatedAt=now;}public void transition(InterviewStatus next,Instant now){status=next;updatedAt=now;}public UUID getId(){return id;}public Application getApplication(){return application;}public Instant getStartsAt(){return startsAt;}public Instant getEndsAt(){return endsAt;}public InterviewStatus getStatus(){return status;}public InterviewLocationType getLocationType(){return locationType;}public String getLocation(){return location;}public String getMeetingUrl(){return meetingUrl;}public User getCreatedBy(){return createdBy;}public long getVersion(){return version;}}
